//! The wire format: the UI's `ScanRequest` in, `ScanResponse` out.
//!
//! The engine works in UTF-8 byte offsets; IPC and `scrub --json` use UTF-16 code units (what
//! JavaScript strings and CodeMirror count). Every offset crosses through [`Utf16Map`].
//! Responses carry offsets, labels and value keys, never a secret value.
//!
//! This crate is the one place that maps engine results to that shape. The desktop app and the
//! `scrub` CLI both use it, so the UI's fixtures (generated by `scrub --json`) are exactly what
//! the app sends. No Tauri here.
#![forbid(unsafe_code)]

pub mod text;

use std::time::Instant;

use redactor_core::{
    Engine, ScanOutcome, ScanRequest, Sensitivity, Source, Tier, Utf16Map, ValueKey, WarningKind,
};
use serde::{Deserialize, Serialize};
use zeroize::Zeroize;

/// Largest input the shell scans: 20 MiB of UTF-8.
pub const MAX_INPUT_BYTES: usize = 20 * 1024 * 1024;

#[derive(Clone, Copy, Debug, Deserialize)]
pub struct RangeIn {
    pub start: usize,
    pub end: usize,
}

/// The UI's scan request. The text is zeroized when the request is dropped (best effort: the
/// IPC layer and the WebView hold their own copies, which Rust cannot reach).
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ScanRequestIn {
    pub text: String,
    pub sensitivity: Sensitivity,
    pub pii: bool,
    pub strip_invisible: bool,
    #[serde(default)]
    pub keep: Vec<String>,
    #[serde(default)]
    pub manual: Vec<RangeIn>,
}

impl Drop for ScanRequestIn {
    fn drop(&mut self) {
        self.text.zeroize();
    }
}

impl std::fmt::Debug for ScanRequestIn {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ScanRequestIn")
            .field("text", &"<hidden>")
            .field("sensitivity", &self.sensitivity)
            .field("pii", &self.pii)
            .finish_non_exhaustive()
    }
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FindingOut {
    pub id: usize,
    pub start: usize,
    pub end: usize,
    pub line: usize,
    pub kind: String,
    pub label: String,
    pub tier: Tier,
    pub confidence: f32,
    pub detector: String,
    pub reason: String,
    pub source: Source,
    pub value_key: ValueKey,
    pub placeholder: String,
    pub kept: bool,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct OutputSpanOut {
    pub start: usize,
    pub end: usize,
    pub finding_id: usize,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum WarningKindOut {
    InvisibleChars,
    BidiControls,
    TagChars,
    DecodeLimit,
    VerifyCapHit,
    InputTooLarge,
}

#[derive(Debug, Serialize)]
pub struct WarningOut {
    pub kind: WarningKindOut,
    pub count: usize,
}

#[derive(Debug, Default, Serialize)]
pub struct ByTier {
    pub certain: usize,
    pub likely: usize,
    pub possible: usize,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct LabelCount {
    pub label: String,
    pub n: usize,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Stats {
    pub ms: f64,
    pub chars: usize,
    pub by_tier: ByTier,
    pub by_label: Vec<LabelCount>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ScanResponseOut {
    pub output: String,
    pub findings: Vec<FindingOut>,
    pub output_spans: Vec<OutputSpanOut>,
    pub warnings: Vec<WarningOut>,
    pub verified: bool,
    pub stats: Stats,
}

impl ScanResponseOut {
    /// Number of redacted (not kept) findings.
    pub fn removed(&self) -> usize {
        self.findings.iter().filter(|f| !f.kept).count()
    }
}

fn warning_kind(k: WarningKind) -> WarningKindOut {
    match k {
        WarningKind::InvisibleChars => WarningKindOut::InvisibleChars,
        WarningKind::BidiControls => WarningKindOut::BidiControls,
        WarningKind::TagChars => WarningKindOut::TagChars,
        WarningKind::DecodeLimit => WarningKindOut::DecodeLimit,
        WarningKind::VerifyCapHit => WarningKindOut::VerifyCapHit,
    }
}

/// Redacted findings per label, most frequent first (ties keep first-seen order).
pub fn by_label<'a>(labels: impl Iterator<Item = &'a str>) -> Vec<LabelCount> {
    let mut out: Vec<LabelCount> = Vec::new();
    for l in labels {
        match out.iter_mut().find(|c| c.label == l) {
            Some(c) => c.n += 1,
            None => out.push(LabelCount {
                label: l.to_string(),
                n: 1,
            }),
        }
    }
    out.sort_by_key(|c| std::cmp::Reverse(c.n));
    out
}

/// Scans `req.text` with `engine` and maps the result to the IPC shape.
pub fn scan(engine: &Engine, req: &ScanRequestIn) -> ScanResponseOut {
    let started = Instant::now();
    let text = req.text.as_str();
    if text.len() > MAX_INPUT_BYTES {
        return ScanResponseOut {
            output: String::new(),
            findings: Vec::new(),
            output_spans: Vec::new(),
            warnings: vec![WarningOut {
                kind: WarningKindOut::InputTooLarge,
                count: text.len(),
            }],
            verified: false,
            stats: Stats {
                ms: 0.0,
                chars: text.encode_utf16().count(),
                by_tier: ByTier::default(),
                by_label: Vec::new(),
            },
        };
    }
    let in_map = Utf16Map::new(text);
    let keep: Vec<ValueKey> = req
        .keep
        .iter()
        .filter_map(|k| ValueKey::from_hex(k))
        .collect();
    let manual: Vec<(usize, usize)> = req
        .manual
        .iter()
        .filter(|r| r.end > r.start)
        .map(|r| (in_map.to_byte(r.start), in_map.to_byte(r.end)))
        .collect();
    let outcome = engine.scan(
        text,
        &ScanRequest {
            sensitivity: Some(req.sensitivity),
            pii: Some(req.pii),
            keep: &keep,
            manual: &manual,
        },
    );
    let mut resp = map_outcome(text, &in_map, outcome);
    resp.stats.ms = (started.elapsed().as_secs_f64() * 10_000.0).round() / 10.0;
    resp
}

/// Maps an engine outcome for `text` to the wire shape (`stats.ms` is 0; the caller times the scan).
pub fn response_from_outcome(text: &str, outcome: ScanOutcome) -> ScanResponseOut {
    map_outcome(text, &Utf16Map::new(text), outcome)
}

fn map_outcome(text: &str, in_map: &Utf16Map, outcome: ScanOutcome) -> ScanResponseOut {
    let ScanOutcome {
        output,
        findings,
        output_spans,
        warnings,
        verified,
    } = outcome;

    // Lines: findings are sorted by start, so count newlines incrementally.
    let bytes = text.as_bytes();
    let mut line = 1usize;
    let mut cursor = 0usize;
    let mut by_tier = ByTier::default();
    let mut out_findings = Vec::with_capacity(findings.len());
    for (id, f) in findings.into_iter().enumerate() {
        let start = f.start.max(cursor);
        line += memchr::memchr_iter(b'\n', &bytes[cursor..start]).count();
        cursor = start;
        if !f.kept {
            match f.tier {
                Tier::Certain => by_tier.certain += 1,
                Tier::Likely => by_tier.likely += 1,
                Tier::Possible => by_tier.possible += 1,
            }
        }
        out_findings.push(FindingOut {
            id,
            start: in_map.to_utf16(f.start),
            end: in_map.to_utf16(f.end),
            line,
            kind: f.kind,
            label: f.label,
            tier: f.tier,
            confidence: f.confidence,
            detector: f.detector,
            reason: f.reason,
            source: f.source,
            value_key: f.value_key,
            placeholder: f.placeholder,
            kept: f.kept,
        });
    }
    let labels = by_label(
        out_findings
            .iter()
            .filter(|f| !f.kept)
            .map(|f| f.label.as_str()),
    );
    let out_map = Utf16Map::new(&output);
    let spans = output_spans
        .iter()
        .map(|s| OutputSpanOut {
            start: out_map.to_utf16(s.start),
            end: out_map.to_utf16(s.end),
            finding_id: s.finding,
        })
        .collect();
    ScanResponseOut {
        output,
        findings: out_findings,
        output_spans: spans,
        warnings: warnings
            .into_iter()
            .map(|w| WarningOut {
                kind: warning_kind(w.kind),
                count: w.count,
            })
            .collect(),
        verified,
        stats: Stats {
            ms: 0.0,
            chars: in_map.utf16_len(),
            by_tier,
            by_label: labels,
        },
    }
}

/// A request with the given settings and no keep/manual (clipboard scrub).
pub fn plain_request(
    text: String,
    sensitivity: Sensitivity,
    pii: bool,
    strip: bool,
) -> ScanRequestIn {
    ScanRequestIn {
        text,
        sensitivity,
        pii,
        strip_invisible: strip,
        keep: Vec::new(),
        manual: Vec::new(),
    }
}
